import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    # Skip blank and comment lines only in the preamble, before CSV parsing.
    stream = io.StringIO(raw_csv, newline="")
    while True:
        start = stream.tell()
        line = stream.readline()
        if not line:
            return {"columns": [], "rows": []}
        if line.strip() and not line.lstrip().startswith("#"):
            break

    # Use the tab hint if it splits the header; otherwise check for commas.
    # Probe logical records so delimiters inside quoted fields do not count.
    delimiter = "\t"
    for candidate in ("\t", ","):
        stream.seek(start)
        reader = csv.reader(stream, delimiter=candidate, quotechar='"', doublequote=True)
        if len(next(reader, [])) > 1:
            delimiter = candidate
            break

    stream.seek(start)
    reader = csv.reader(stream, delimiter=delimiter, quotechar='"', doublequote=True)
    columns = next(reader, [])
    rows = []
    width = len(columns)
    for row in reader:
        rows.append(row)
        width = max(width, len(row))

    # Preserve excess fields with new columns and pad short records.
    used_names = set(columns)
    suffix = 1
    while len(columns) < width:
        name = f"extra_{suffix}"
        suffix += 1
        if name not in used_names:
            columns.append(name)
            used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
